  "st.fixedSub": ["Ayə təmizdir. Davam edə bilərsiniz.", "Ayet hatasız. Devam edebilirsiniz.", "The ayah is clean. You can continue.", "الآية سليمة. يمكنك المتابعة.", "Аят чистый. Можно продолжать.", "Le verset est juste. Vous pouvez continuer.", "Ayat sudah benar. Anda bisa lanjut.", "আয়াতটি নির্ভুল। এগিয়ে যেতে পারেন।", "Ayat sudah betul. Anda boleh teruskan.", "آیت درست ہے۔ آپ آگے بڑھ سکتے ہیں۔", "آیه پاک است. می‌توانید ادامه دهید.", "La aleya está correcta. Puede continuar.", "Die Āya ist sauber. Sie können fortfahren."],
  "st.held": ["Buraxıldı", "Atlandı", "Skipped", "تُركت", "Пропущено", "Sauté", "Terlewat", "বাদ পড়েছে", "Tertinggal", "چھوٹ گئی", "جا افتاده", "Omitida", "Übersprungen"],
  "st.heldSub": ["{p} bitməyib. Növbəti ayə açılmır.", "{p} bitmedi. Sonraki ayet açılmaz.", "{p} is not finished. The next ayah stays hidden.", "{p} لم تكتمل. لن تظهر الآية التالية.", "{p} не закончен. Следующий аят не откроется.", "{p} n'est pas terminé. Le verset suivant reste caché.", "{p} belum selesai. Ayat berikutnya tetap tersembunyi.", "{p} শেষ হয়নি। পরের আয়াত লুকানো থাকবে।", "{p} belum selesai. Ayat seterusnya kekal tersembunyi.", "{p} مکمل نہیں ہوئی۔ اگلی آیت چھپی رہے گی۔", "{p} تمام نشده. آیه بعد پنهان می‌ماند.", "{p} no está terminada. La siguiente aleya sigue oculta.", "{p} ist nicht beendet. Die nächste Āya bleibt verborgen."],
  "st.listening": ["Dinləyirəm", "Dinliyorum", "Listening", "أستمع", "Слушаю", "J'écoute", "Mendengarkan", "শুনছি", "Mendengar", "سن رہا ہوں", "می‌شنوم", "Escuchando", "Ich höre zu"],
  "st.wordFixed": ["{p} — söz düzəldi. Ayəni bitirin.", "{p} — kelime düzeldi. Ayeti bitirin.", "{p} — word fixed. Finish the ayah.", "{p} — صُحّحت الكلمة. أكمل الآية.", "{p} — слово исправлено. Закончите аят.", "{p} — mot corrigé. Terminez le verset.", "{p} — kata diperbaiki. Selesaikan ayatnya.", "{p} — শব্দ ঠিক হয়েছে। আয়াতটি শেষ করুন।", "{p} — perkataan dibetulkan. Habiskan ayat.", "{p} — لفظ درست ہو گیا۔ آیت مکمل کریں۔", "{p} — واژه اصلاح شد. آیه را تمام کنید.", "{p} — palabra corregida. Termine la aleya.", "{p} — Wort korrigiert. Beenden Sie die Āya."],
  "err.open": ["{x} açılmadı", "{x} açılamadı", "Could not open {x}", "تعذّر فتح {x}", "Не удалось открыть: {x}", "Impossible d'ouvrir {x}", "Tidak dapat membuka {x}", "{x} খোলা যায়নি", "Tidak dapat membuka {x}", "{x} نہیں کھل سکا", "نشد {x} را باز کرد", "No se pudo abrir {x}", "{x} konnte nicht geöffnet werden"],
  "st.model": ["Model yüklənir", "Model yükleniyor", "Loading model", "جارٍ تحميل النموذج", "Загрузка модели", "Chargement du modèle", "Memuat model", "মডেল লোড হচ্ছে", "Memuatkan model", "ماڈل لوڈ ہو رہا ہے", "بارگذاری مدل", "Cargando el modelo", "Modell wird geladen"],
  "st.modelSub": ["Bir dəfə, təxminən 85 MB (model, lüğət və mühərrik). Sonra telefonda qalır.", "Bir kez, yaklaşık 85 MB (model, sözlük ve motor). Sonra telefonda kalır.", "Once, about 85 MB (model, lexicon and engine). Then it stays on the phone.", "مرة واحدة، نحو 85 ميغابايت (النموذج والمعجم والمحرّك). ثم يبقى على الهاتف.", "Один раз, около 85 МБ (модель, словарь и движок). Потом остаётся на телефоне.", "Une seule fois, environ 85 Mo (modèle, lexique et moteur). Ensuite il reste sur le téléphone.", "Sekali saja, sekitar 85 MB (model, leksikon, dan mesin). Setelah itu tersimpan di ponsel.", "একবারই, প্রায় ৮৫ MB (মডেল, শব্দকোষ ও ইঞ্জিন)। এরপর ফোনেই থাকে।", "Sekali sahaja, kira-kira 85 MB (model, leksikon dan enjin). Selepas itu ia kekal di telefon.", "صرف ایک بار، تقریباً 85 MB (ماڈل، لغت اور انجن)۔ پھر فون میں ہی رہتا ہے۔", "یک‌بار، حدود ۸۵ مگابایت (مدل، واژه‌نامه و موتور). سپس روی گوشی می‌ماند.", "Una vez, unos 85 MB (modelo, léxico y motor). Luego permanece en el teléfono.", "Einmalig, etwa 85 MB (Modell, Lexikon und Engine). Danach bleibt es auf dem Telefon."],
  "st.lex": ["Lüğət açılır", "Sözlük açılıyor", "Opening lexicon", "جارٍ فتح المعجم", "Открывается словарь", "Ouverture du lexique", "Membuka leksikon", "শব্দকোষ খোলা হচ্ছে", "Membuka leksikon", "لغت کھل رہی ہے", "گشودن واژه‌نامه", "Abriendo el léxico", "Lexikon wird geöffnet"],
  "st.lexSub": ["Ayə sözləri hazırlanır…", "Ayet kelimeleri hazırlanıyor…", "Preparing ayah words…", "تجهيز كلمات الآيات…", "Подготовка слов аятов…", "Préparation des mots des versets…", "Menyiapkan kata-kata ayat…", "আয়াতের শব্দ প্রস্তুত হচ্ছে…", "Menyediakan perkataan ayat…", "آیات کے الفاظ تیار ہو رہے ہیں…", "آماده‌سازی واژه‌های آیه…", "Preparando las palabras de la aleya…", "Āya-Wörter werden vorbereitet…"],
