  "st.repeatSub": ["{p} — ayəni yenidən oxuyun", "{p} — ayeti yeniden okuyun", "{p} — read the ayah again", "{p} — أعد قراءة الآية", "{p} — прочитайте аят ещё раз", "{p} — relisez le verset", "{p} — baca ayat ini lagi", "{p} — আয়াতটি আবার পড়ুন", "{p} — baca ayat ini sekali lagi", "{p} — آیت دوبارہ پڑھیں", "{p} — آیه را دوباره بخوانید", "{p} — lea la aleya de nuevo", "{p} — lesen Sie die Āya noch einmal"],
  "st.onlyHere": ["{p} — yalnız bu yer gizlidir", "{p} — yalnızca bu yer gizli", "{p} — only this spot is hidden", "{p} — هذا الموضع فقط مخفي", "{p} — скрыто только это место", "{p} — seul cet endroit est caché", "{p} — hanya bagian ini yang disembunyikan", "{p} — শুধু এই জায়গাটি লুকানো", "{p} — hanya bahagian ini disembunyikan", "{p} — صرف یہ جگہ چھپی ہے", "{p} — فقط این موضع پنهان است", "{p} — solo este lugar está oculto", "{p} — nur diese Stelle ist verborgen"],
  "err.mic": ["Mikrofon açılmadı", "Mikrofon açılamadı", "The microphone could not start", "تعذّر تشغيل الميكروفون", "Не удалось включить микрофон", "Le microphone n'a pas pu démarrer", "Mikrofon tidak dapat dimulai", "মাইক্রোফোন চালু করা যায়নি", "Mikrofon tidak dapat dimulakan", "مائیکروفون شروع نہیں ہو سکا", "میکروفون روشن نشد", "El micrófono no pudo iniciarse", "Das Mikrofon konnte nicht gestartet werden"],
