  "tj.head": ["Ayə {a} — təcvid rəyi", "Ayet {a} — tecvid yorumu", "Ayah {a} — tajwid review", "الآية {a} — ملاحظات التجويد", "Аят {a} — разбор таджвида", "Verset {a} — revue tajwid", "Ayat {a} — tinjauan tajwid", "আয়াত {a} — তাজবীদ পর্যালোচনা", "Ayat {a} — semakan tajwid", "آیت {a} — تجوید جائزہ", "آیه {a} — بررسی تجوید", "Aleya {a} — revisión de tayyid", "Āya {a} — Tadschwid-Prüfung"],
